spec.setup_code:
var cylGeom = new api.THREE.CylinderGeometry(1, 1, 2, 24, 1, true);
                var cylMat = new api.THREE.MeshBasicMaterial({ color: 0x8A8272, wireframe: true });
                var cylMesh = new api.THREE.Mesh(cylGeom, cylMat);
                api.group.add(cylMesh);
                var axes = new api.THREE.AxesHelper(2.5);
                api.group.add(axes);
                var pointGeom = new api.THREE.SphereGeometry(0.12, 16, 16);
                var pointMat = new api.THREE.MeshPhongMaterial({ color: 0xE8593C });
                var point = new api.THREE.Mesh(pointGeom, pointMat);
                api.group.add(point);
                var r = 1;
                return {
                  update: function(t) {
                    var theta = t * 0.02;
                    var z = Math.sin(t * 0.01) * 0.8;
                    point.position.set(r * Math.cos(theta), z, r * Math.sin(theta));
                  }
                };

return {
                  draw: function(ctx, W, H, t, dt) {
                    ctx.fillStyle = '#F5F0E8';
                    ctx.fillRect(0, 0, W, H);
                    var cx = W * 0.4, cy = H/2;
                    var R = Math.min(W, H) * 0.28;
                    ctx.strokeStyle = '#CFC7B8';
                    ctx.beginPath();
                    ctx.arc(cx, cy, R, 0, Math.PI * 2);
                    ctx.stroke();
                    var theta = t * 0.03;
                    var x = cx + R * Math.cos(theta);
                    var y = cy - R * Math.sin(theta);
                    ctx.strokeStyle = '#8A8272';
                    ctx.beginPath();
                    ctx.moveTo(cx, cy); ctx.lineTo(x, y);
                    ctx.stroke();
                    ctx.fillStyle = '#E8593C';
                    ctx.beginPath();
                    ctx.arc(x, y, 8, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.fillStyle = '#333';
                    ctx.font = '13px sans-serif';
                    ctx.fillText('top view: (r, \u03B8)', cx - R, cy - R - 12);
                    var barX = W * 0.82, barTop = H * 0.15, barBottom = H * 0.85;
                    ctx.strokeStyle = '#8A8272';
                    ctx.beginPath();
                    ctx.moveTo(barX, barTop); ctx.lineTo(barX, barBottom);
                    ctx.stroke();
                    var zNorm = (Math.sin(t * 0.015) + 1) / 2;
                    var zY = barBottom - zNorm * (barBottom - barTop);
                    ctx.fillStyle = '#E8593C';
                    ctx.beginPath();
                    ctx.arc(barX, zY, 8, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.fillText('height z', barX - 24, barTop - 12);
                  }
                };
